    + pickN(C.sections, seed + ':bsec', 2).map(s => angleSection(s, ctx, seed)).join('')
    + sec(fill(SITE.casesH2, ctx), `<div class="grid">${pickN(forProd(C.cases, ctx._p), seed + ':case', 2).map((c, i) => `<div class="card"><h3>${esc(fill(c.t, ctx))}</h3><p>${esc(para(c.d, ctx, seed + i))}</p></div>`).join('')}</div>`)
    + sec(`다른 업종 ${prod.ko}`, links(BIZ.filter(x => x.slug !== b.slug).map(x => ({ name: x.ko, href: `/${prod.key}/biz/${x.slug}/` }))))
    + (ACTIVE.length > 1 ? sec(`${b.ko} ${SITE.bizOtherProducts}`, links(ACTIVE.filter(p => p.key !== prod.key).map(p => ({ name: `${b.ko} ${p.ko}`, href: `/${p.key}/biz/${b.slug}/` })))) : '');
